  const phi = rand() * TAU;
  if (Math.abs(n.y) < 0.95) _tA.set(0, 1, 0); else _tA.set(1, 0, 0);
  _tA.cross(n).normalize();
  _tB.copy(n).cross(_tA);
  return out.copy(n).multiplyScalar(z).addScaledVector(_tA, r * Math.cos(phi)).addScaledVector(_tB, r * Math.sin(phi));
}

